import org.apache.log4j.Logger;

  import sailpoint.object.Application;
  import sailpoint.object.Custom;
  import sailpoint.object.Identity;
  import sailpoint.api.IdentityService;
  import sailpoint.object.QueryOptions;
  import sailpoint.object.Filter;
  import sailpoint.tools.Util;

  Logger log = Logger.getLogger("iiq.alpha.Alpha-ActiveDirectory-Correlation-Rule");
  log.debug("Alpha-ActiveDirectory-Correlation-Rule - STARTS");

  Map correlationMap = new HashMap();
  String applicationName = application.getName();
  //log.debug(account.toXml());
  log.debug(link);
  try{
    Identity identity = null;
    if("serviceAccount".equalsIgnoreCase(account.getStringAttribute("extensionName")))
    {
      log.debug("serviceAccount"+account.getStringAttribute("sAMAccountName"));
      String correlarionIdentityName = (String) getValueFromCustomObject("Alpha-Custom-CorreationMapping-CustomObject-test",applicationName);
      log.debug("correlarionIdentityName"+correlarionIdentityName);
      identity = context.getObjectByName(Identity.class,correlarionIdentityName);
      if(identity != null)
      {
        correlationMap.put("identity",identity);
      }
      else{
        log.debug("Could not find Identity for "+account.getStringAttribute("sAMAccountName"));
      }
    }
    else if(Util.isNotNullOrEmpty(account.getStringAttribute("employeeNumber")))
    {
      String employeeNumber = account.getStringAttribute("employeeNumber");
      log.debug("employeeNumber:"+employeeNumber);
      identity = context.getUniqueObject(Identity.class,Filter.eq("employeeId",employeeNumber));
      if(identity != null)
      {
        correlationMap.put("identity",identity);
      }
      else{
        log.debug("Could not find Identity for "+employeeNumber);
      }
    }
  }catch(Exception e){
    log.error("Alpha-ActiveDirectory-Correlation-Rule - cought exception:"+e);
  }
  log.debug("Alpha-ActiveDirectory-Correlation-Rule -END");
  return correlationMap;
